package com.secure.documentwallet;

import android.content.*;

/** Vault palettes. Document previews keep their own neutral paper/card surface. */
final class ThemeManager {
 static final String EMERALD="emerald",OCEAN="ocean",SAND="sand",DARK="dark",GLASS="glass";private static final String PREF="appearance",KEY="theme";
 static String current(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE).getString(KEY,EMERALD);}
 static int selected(Context c){String value=current(c);return OCEAN.equals(value)?1:SAND.equals(value)?2:DARK.equals(value)?3:GLASS.equals(value)?4:0;}
 static void set(Context c,int index){String value=index==1?OCEAN:index==2?SAND:index==3?DARK:index==4?GLASS:EMERALD;c.getSharedPreferences(PREF,Context.MODE_PRIVATE).edit().putString(KEY,value).apply();apply(c);}
 static boolean dark(Context c){return DARK.equals(current(c));}
 static void apply(Context c){String value=current(c);if(OCEAN.equals(value)){Ui.NAVY=0xff12364f;Ui.TEAL=0xff147fa3;Ui.BG=0xfff3f7fa;Ui.INK=0xff172b39;Ui.MUTED=0xff607682;Ui.SOFT=0xffe3f1f7;Ui.BORDER=0xffc5dde8;Ui.ACCENT_DARK=0xff185f7c;Ui.GOLD=0xffd5a542;Ui.SURFACE=0xffffffff;}else if(SAND.equals(value)){Ui.NAVY=0xff49372c;Ui.TEAL=0xffa5653e;Ui.BG=0xfffbf7ef;Ui.INK=0xff30251f;Ui.MUTED=0xff75685e;Ui.SOFT=0xfff3e8d9;Ui.BORDER=0xffe1cdb5;Ui.ACCENT_DARK=0xff80513a;Ui.GOLD=0xffc98c31;Ui.SURFACE=0xfffffdf9;}else if(DARK.equals(value)){Ui.NAVY=0xffd8f5ef;Ui.TEAL=0xff46d7c2;Ui.BG=0xff0b1413;Ui.INK=0xfff1f7f5;Ui.MUTED=0xffa7b9b4;Ui.SOFT=0xff162725;Ui.BORDER=0xff31514b;Ui.ACCENT_DARK=0xff137f72;Ui.GOLD=0xffe6b957;Ui.SURFACE=0xff14201f;}else if(GLASS.equals(value)){Ui.NAVY=0xff243555;Ui.TEAL=0xff397cc8;Ui.BG=0xffeaf3ff;Ui.INK=0xff17243b;Ui.MUTED=0xff62728c;Ui.SOFT=0xdde7f4ff;Ui.BORDER=0xffbfd3ed;Ui.ACCENT_DARK=0xff4166b0;Ui.GOLD=0xffd5a951;Ui.SURFACE=0xeef8fbff;}else{Ui.NAVY=0xff12372f;Ui.TEAL=0xff159a8c;Ui.BG=0xfff5f7f6;Ui.INK=0xff192724;Ui.MUTED=0xff64746f;Ui.SOFT=0xffe7f3ef;Ui.BORDER=0xffc8ddd6;Ui.ACCENT_DARK=0xff0b665f;Ui.GOLD=0xffd6a947;Ui.SURFACE=0xffffffff;}}
 static int headerStart(Context c){return OCEAN.equals(current(c))?0xff102e48:SAND.equals(current(c))?0xff432f23:DARK.equals(current(c))?0xff050b0a:GLASS.equals(current(c))?0xff2f4773:0xff0d302c;}
 static int headerEnd(Context c){return OCEAN.equals(current(c))?0xff167da0:SAND.equals(current(c))?0xffa5653e:DARK.equals(current(c))?0xff126b60:GLASS.equals(current(c))?0xff7b84d8:0xff0b8177;}
 static int tileStart(Context c,int index){String t=current(c);int[] values=OCEAN.equals(t)?new int[]{0xff167fa2,0xff4869ad,0xff21699d,0xff2a7b78,0xff6851a3,0xffa44f77}:SAND.equals(t)?new int[]{0xff9b6543,0xffb57a26,0xff8b5a43,0xff73804b,0xff75536f,0xffa64f4f}:DARK.equals(t)?new int[]{0xff116b60,0xff745b22,0xff245c83,0xff275f50,0xff594286,0xff873c50}:GLASS.equals(t)?new int[]{0xff4b83c4,0xff8877c7,0xff4e98b3,0xff4a9c8d,0xff8b6bb8,0xffbe709b}:new int[]{0xff0f897c,0xffb27a19,0xff236ca3,0xff2b7b66,0xff6b4bae,0xffbd5267};return values[index%values.length];}
 static int tileEnd(Context c,int index){String t=current(c);int[] values=OCEAN.equals(t)?new int[]{0xff28abc2,0xff718bc9,0xff3b91c8,0xff4aa6a1,0xff9278ca,0xffd5779b}:SAND.equals(t)?new int[]{0xffc78a5d,0xffdda847,0xffb57d61,0xff9ba461,0xff9e7596,0xffd87969}:DARK.equals(t)?new int[]{0xff159988,0xffa17d2b,0xff327dad,0xff32816b,0xff7659ad,0xffb44e69}:GLASS.equals(t)?new int[]{0xff72b6dc,0xffaaa0e5,0xff78c6d9,0xff76cdb9,0xffb19ad8,0xffe6a0bd}:new int[]{0xff16b39f,0xffe0a62a,0xff3d91c4,0xff47a887,0xff9b72d0,0xffef7c72};return values[index%values.length];}
}
